#include <math.h>

typedef struct {
    int x;
    int y;
} Ponto;

int oPontoMaisLonge(Ponto pontos[], int n) {
    int melhor = 0;
    double maior = 0.0;

    for (int i = 0; i < n; i++) {
        double d = sqrt(pontos[i].x * pontos[i].x + pontos[i].y * pontos[i].y);
        if (maior < d) {
            maior = d;
            melhor = i;
        }
    }

    return melhor;
}
